import {
  ImageBackground,
  StyleSheet,
  Text,
  View,
  ScrollView,
} from "react-native";
import React from "react";
import { useNavigation } from "@react-navigation/native";

const HomeScreen1 = () => {
  const navigation = useNavigation();
  const image = {
    uri: "https://firebasestorage.googleapis.com/v0/b/swapper-stu.appspot.com/o/Assets%2Fproducts-banner-image.png?alt=media&token=bfe79d05-c67c-4bf2-98f7-3dd80e1c1829",
  };

  return (
    <View className="flex-1">
      <ScrollView>
        <ImageBackground source={image} resizeMode="cover" style={styles.image} className="h-screen">
          <View>
            <Text style={styles.text}>
              Lo que necesitas para tus estudios en un solo lugar
            </Text>
          </View>
        </ImageBackground>
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  image: {
    flex: 1,
    justifyContent: "center",
    backgroundPosition: "left",
  },
  text: {
    width: "100%",
    color: "black",
    fontSize: 70,
    lineHeight: 84,
    fontWeight: "bold",
    paddingTop: 70,
    maxWidth: 500,
    padding: 20,
  },
});

export default HomeScreen1;
